/**
 * The one slugification rule, shared by the admin editor and the backfill that
 * gave every article translation its slug.
 *
 * Deterministic on purpose: the same title must always produce the same slug,
 * so a slug generated by hand in the editor matches the one the migration
 * computed for the same text. Keep this in step with
 * `back/prisma/migrations/20260824140000_add_article_translation_slug`.
 */

/**
 * Words dropped when they open or close a title. They carry no meaning in a
 * URL, and the slug is often the only text an assistant sees before deciding
 * whether to open the page. They are only stripped at the ends: removing them
 * from the middle would turn "instead of paying" into "instead paying".
 */
const EDGE_STOP_WORDS = new Set([
    'a',
    'an',
    'the',
    'of',
    'for',
    'to',
    'and',
    'with',
    'on',
    'in',
    'at',
    'by',
    'from',
    'that',
    'has',
    'have',
    'i',
    'you',
    'it',
    'is',
    'are',
    'not',
    'without',
    'through',
    'instead',
    'all',
    'my',
    'one',
    'into',
    'as',
    'its',
    'so',
]);

/** Longest slug we emit. Past this, readability stops paying for itself. */
const MAX_LENGTH = 55;

/**
/** Drop opening and closing stop-words. */
function trimStopWords(words: string[]): string[] {
    const trimmed = [...words];
    while (trimmed.length > 1 && EDGE_STOP_WORDS.has(trimmed[0]))
        trimmed.shift();
    while (
        trimmed.length > 1 &&
        EDGE_STOP_WORDS.has(trimmed[trimmed.length - 1])
    )
        trimmed.pop();
    return trimmed;
}

/**
 * Turn a title into a kebab-case slug.
 *
 * Accents are folded to ASCII and apostrophes are dropped rather than turned
 * into a separator, so "Don't Own" reads `dont-own` and "qu'on" reads `quon`
 * instead of splitting into two stubs. The result is truncated on a word
 * boundary, never mid-word.
 *
 * Stop-words are trimmed twice, once before the truncation and once after:
 * cutting a long title regularly leaves a preposition dangling at the end
 * ("...-instead-of-paying-for-a"), which the second pass removes.
 */
export function slugify(input: string): string {
    const words = trimStopWords(
        input
            .normalize('NFKD')
            .replace(/[̀-ͯ]/g, '')
            .replace(/['’]/g, '')
            .toLowerCase()
            .split(/[^a-z0-9]+/)
            .filter(Boolean)
    );

    const kept: string[] = [];
    let length = 0;
    for (const word of words) {
        const next = length === 0 ? word.length : length + 1 + word.length;
        if (kept.length && next > MAX_LENGTH) break;
        kept.push(word);
        length = next;
    }

    return trimStopWords(kept).join('-');
}
